const defaultStart = "2025-01-01T00:00:00.000Z";

let lastSyncAt = flow.get("salesOrdersLastSyncAt") || defaultStart;

// Kleine overlap om records met gelijke seconde/timestamp niet te missen.
// Let op: hierdoor kan een record soms opnieuw gepost worden. Zorg dat UMH upsert/idempotent is op order_id.
const overlapMs = 2 * 60 * 1000;
const queryFromDate = new Date(new Date(lastSyncAt).getTime() - overlapMs);

msg.limit = limit;
