msg.lastSyncAt = lastSyncAt;
msg.queryFrom = queryFromDate.toISOString();
msg.maxSeenAt = lastSyncAt;

node.status({ text: "Sinds " + msg.queryFrom });
return msg;

const BASE_URL = "http://nocodb:8080";
const TABLE_ID = "mbbx07gmu8col2j";

const limit = msg.limit || 25;
const offset = msg.offset || 0;

function formatForNocoDB(iso) {
    const d = new Date(iso);
    const pad = n => String(n).padStart(2, "0");
    return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}:${pad(d.getUTCSeconds())}+00:00`;
}

const since = formatForNocoDB(msg.queryFrom);
const where = `(CreatedAt,gt,${since})~or(UpdatedAt,gt,${since})`;

msg.url = `${BASE_URL}/api/v2/tables/${TABLE_ID}/records?limit=${limit}&shuffle=0&offset=${offset}&where=${encodeURIComponent(where)}`;

return msg;

