const messages = [];

function toIso(value) {
    if (!value) return null;
    return new Date(String(value).replace(" ", "T")).toISOString();
}

let maxSeenAt = msg.maxSeenAt || msg.lastSyncAt;

for (const r of rows) {
    const createdIso = toIso(r.CreatedAt);
    const updatedIso = toIso(r.UpdatedAt);
    const changedIso = updatedIso || createdIso;

    if (changedIso && new Date(changedIso) > new Date(maxSeenAt)) {
        maxSeenAt = changedIso;
    }

    messages.push({
        payload: JSON.stringify({
            order_id: r.order_id || r.Title || String(r.Id),
            customer_name: r.customer_name || "",
            status: r.status || "Open",
            milestone: r.milestone || r.status || "Open",
            due_date: r.due_date || null,
            order_date: r.order_date || null,
            delivered_date: null,
            source_created_at: createdIso,
            source_updated_at: updatedIso,
            source_changed_at: changedIso
        }),
        headers: { "Content-Type": "application/json" },
        maxSeenAt: maxSeenAt,
        offset: msg.offset,
        limit: msg.limit,
        queryFrom: msg.queryFrom,
        lastSyncAt: msg.lastSyncAt
    });
}

msg.maxSeenAt = maxSeenAt;
node.status({ text: rows.length + " records" });
return [messages];

